use serde::{Deserialize,Serialize};
use std::collections::BTreeMap;
pub const EMBEDDING_DIMENSIONS:usize=384;
#[derive(Debug,Deserialize)]#[serde(tag="op",rename_all="snake_case")]pub enum Request{Health,Chunk{content:String,#[serde(default)]language:Option<String>,#[serde(default="default_chunk_bytes")]max_bytes:usize},Embed{text:String},Analyze{content:String,#[serde(default)]language:Option<String>}}
fn default_chunk_bytes()->usize{2400}
#[derive(Debug,Serialize)]pub struct Response{pub ok:bool,pub engine:&'static str,pub version:&'static str,#[serde(skip_serializing_if="Option::is_none")]pub result:Option<serde_json::Value>,#[serde(skip_serializing_if="Option::is_none")]pub error:Option<String>}
impl Response{fn success(v:serde_json::Value)->Self{Self{ok:true,engine:"brightdesk-engine",version:env!("CARGO_PKG_VERSION"),result:Some(v),error:None}}fn failure(e:&str)->Self{Self{ok:false,engine:"brightdesk-engine",version:env!("CARGO_PKG_VERSION"),result:None,error:Some(e.into())}}}
pub fn handle(r:Request)->Response{match r{Request::Health=>Response::success(serde_json::json!({"status":"ready","capabilities":["source_chunking","lexical_features","source_analysis"]})),Request::Chunk{content,language,max_bytes}=>{if !(128..=16000).contains(&max_bytes){return Response::failure("max_bytes must be between 128 and 16000");}let chunks=chunk_source(&content,max_bytes);Response::success(serde_json::json!({"language":language.unwrap_or_else(||"unknown".into()),"count":chunks.len(),"chunks":chunks}))},Request::Embed{text}=>Response::success(serde_json::json!({"kind":"local_lexical_feature_vector","semantic":false,"dimensions":EMBEDDING_DIMENSIONS,"vector":lexical_embedding(&text)})),Request::Analyze{content,language}=>{let tokens=tokenize(&content);let mut counts=BTreeMap::new();for t in &tokens{*counts.entry(t.clone()).or_insert(0usize)+=1;}let mut top:Vec<_>=counts.into_iter().collect();top.sort_by(|a,b|b.1.cmp(&a.1).then_with(||a.0.cmp(&b.0)));top.truncate(20);Response::success(serde_json::json!({"language":language.unwrap_or_else(||"unknown".into()),"bytes":content.len(),"lines":content.lines().count(),"token_count":tokens.len(),"top_tokens":top.into_iter().map(|(token,count)|serde_json::json!({"token":token,"count":count})).collect::<Vec<_>>()}))}}}
pub fn chunk_source(s:&str,max:usize)->Vec<String>{if s.is_empty(){return vec![];}let mut out=vec![];let mut cur=String::new();for line in s.lines(){let part=format!("{line}\n");if !cur.is_empty()&&cur.len()+part.len()>max{out.push(cur.trim_end_matches('\n').to_string());cur.clear();}if part.len()>max{if !cur.is_empty(){out.push(cur.trim_end_matches('\n').to_string());cur.clear();}let mut i=0;while i<line.len(){let mut j=(i+max).min(line.len());while !line.is_char_boundary(j){j-=1;}out.push(line[i..j].into());i=j;}}else{cur.push_str(&part);}}if !cur.is_empty(){out.push(cur.trim_end_matches('\n').into());}out}
fn tokenize(s:&str)->Vec<String>{s.split(|c:char|!(c.is_alphanumeric()||c=='_'||c=='$')).filter(|x|x.chars().count()>1).map(str::to_lowercase).collect()}
pub fn lexical_embedding(s:&str)->Vec<f32>{let mut v=vec![0.0;EMBEDDING_DIMENSIONS];for t in tokenize(s){let mut h=2166136261u32;for b in t.bytes(){h^=u32::from(b);h=h.wrapping_mul(16777619);}v[h as usize%EMBEDDING_DIMENSIONS]+=if h>>31==0{1.0}else{-1.0};}let n=v.iter().map(|x|x*x).sum::<f32>().sqrt();if n>0.0{for x in &mut v{*x/=n;}}v}
#[cfg(test)]mod tests{use super::*;#[test]fn health(){assert_eq!(handle(Request::Health).result.unwrap()["status"],"ready");}#[test]fn unicode_chunks(){let s="🦀".repeat(100);let c=chunk_source(&s,128);assert!(c.iter().all(|x|x.len()<=128));assert_eq!(c.concat(),s);}#[test]fn vectors_repeat(){assert_eq!(lexical_embedding("Brightdesk Rust"),lexical_embedding("Brightdesk Rust"));}#[test]fn invalid_limit(){assert!(!handle(Request::Chunk{content:"x".into(),language:None,max_bytes:1}).ok);}}
